        "Let's go" to "ಹೋಗೋಣ",
        "Navigating on your car screen" to "ನಿಮ್ಮ ಕಾರಿನ ಪರದೆಯಲ್ಲಿ ನ್ಯಾವಿಗೇಟ್ ಮಾಡುತ್ತಿದೆ",
        "Horizon Nav is on your car screen" to "Horizon Nav ನಿಮ್ಮ ಕಾರಿನ ಪರದೆಯಲ್ಲಿದೆ",
        "Your destination" to "ನಿಮ್ಮ ಗಮ್ಯಸ್ಥಾನ",
        "Pick where to go on the car screen, or share a place to Horizon Nav from any app and it appears there." to "ಕಾರಿನ ಪರದೆಯಲ್ಲಿ ಎಲ್ಲಿಗೆ ಹೋಗಬೇಕೆಂದು ಆರಿಸಿ, ಅಥವಾ ಯಾವುದೇ ಆ್ಯಪ್‌ನಿಂದ Horizon Nav ಗೆ ಸ್ಥಳವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ, ಅದು ಅಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.",
        "Show the map here" to "ನಕ್ಷೆಯನ್ನು ಇಲ್ಲಿ ತೋರಿಸಿ",
        "my destination" to "ನನ್ನ ಗಮ್ಯಸ್ಥಾನ",
        "I'm on my way to {0}" to "ನಾನು {0} ಗೆ ಹೋಗುತ್ತಿದ್ದೇನೆ",
        ", arriving about {0}" to ", ಸುಮಾರು {0} ಕ್ಕೆ ತಲುಪುತ್ತೇನೆ",
        ". Where I am now: https://maps.google.com/?q={0},{1}" to ". ನಾನು ಈಗ ಇರುವ ಸ್ಥಳ: https://maps.google.com/?q={0},{1}",
        "No messaging app available" to "ಸಂದೇಶ ಆ್ಯಪ್ ಲಭ್ಯವಿಲ್ಲ",
        "Contact saved. Tap share again to send." to "ಸಂಪರ್ಕ ಉಳಿಸಲಾಗಿದೆ. ಕಳುಹಿಸಲು ಮತ್ತೆ ಹಂಚಿಕೆ ಟ್ಯಾಪ್ ಮಾಡಿ.",
        "Choose who to send your ETA to" to "ನಿಮ್ಮ ತಲುಪುವ ಸಮಯವನ್ನು ಯಾರಿಗೆ ಕಳುಹಿಸಬೇಕು ಎಂದು ಆರಿಸಿ",
        "Mapbox answered \"401\" for the key you saved, so the map can't load. Make a fresh one at account.mapbox.com › Tokens › " to "ನೀವು ಉಳಿಸಿದ ಕೀಗೆ Mapbox \"401\" ಎಂದು ಉತ್ತರಿಸಿದೆ, ಆದ್ದರಿಂದ ನಕ್ಷೆ ಲೋಡ್ ಆಗುವುದಿಲ್ಲ. account.mapbox.com › Tokens ನಲ್ಲಿ ಹೊಸದನ್ನು ಮಾಡಿ › ",
        "Create a token: name it Horizon Nav, leave the public scopes ticked and the secret ones unticked, then paste it below." to "ಟೋಕನ್ ರಚಿಸಿ: ಅದಕ್ಕೆ Horizon Nav ಎಂದು ಹೆಸರಿಡಿ, ಸಾರ್ವಜನಿಕ ಸ್ಕೋಪ್‌ಗಳನ್ನು ಟಿಕ್ ಮಾಡಿದಂತೆಯೇ ಮತ್ತು ರಹಸ್ಯವಾದವುಗಳನ್ನು ಟಿಕ್ ಮಾಡದೆ ಬಿಡಿ, ನಂತರ ಅದನ್ನು ಕೆಳಗೆ ಅಂಟಿಸಿ.",
        "Horizon Nav now draws its map with Mapbox. Your free Mapbox key adds the 3D map with buildings, trees and lane markings, " to "Horizon Nav ಈಗ Mapbox ನೊಂದಿಗೆ ನಕ್ಷೆಯನ್ನು ಚಿತ್ರಿಸುತ್ತದೆ. ನಿಮ್ಮ ಉಚಿತ Mapbox ಕೀ ಕಟ್ಟಡಗಳು, ಮರಗಳು ಮತ್ತು ಲೇನ್ ಗುರುತುಗಳೊಂದಿಗೆ 3D ನಕ್ಷೆಯನ್ನು, ",
        "live traffic on your route, and better search and speed limits." to "ನಿಮ್ಮ ಮಾರ್ಗದಲ್ಲಿ ನೇರ ಟ್ರಾಫಿಕ್, ಮತ್ತು ಉತ್ತಮ ಹುಡುಕಾಟ ಹಾಗೂ ವೇಗ ಮಿತಿಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ.",
        "Get it at account.mapbox.com › Tokens: copy the Default public token (it starts pk.)." to "account.mapbox.com › Tokens ನಲ್ಲಿ ಪಡೆಯಿರಿ: Default public token ಅನ್ನು ನಕಲಿಸಿ (ಅದು pk. ಯಿಂದ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ).",
        "That's a secret token: use the public one (pk.) here." to "ಅದು ರಹಸ್ಯ ಟೋಕನ್: ಇಲ್ಲಿ ಸಾರ್ವಜನಿಕವಾದದ್ದನ್ನು (pk.) ಬಳಸಿ.",
        "That doesn't look like a whole token yet: it's a long code starting pk." to "ಅದು ಇನ್ನೂ ಪೂರ್ಣ ಟೋಕನ್‌ನಂತೆ ಕಾಣುವುದಿಲ್ಲ: ಅದು pk. ಯಿಂದ ಪ್ರಾರಂಭವಾಗುವ ಉದ್ದದ ಕೋಡ್.",
        "Part of that token looks missing or mistyped. Copy it again with the copy button at account.mapbox.com › Tokens." to "ಆ ಟೋಕನ್‌ನ ಒಂದು ಭಾಗ ಕಾಣೆಯಾಗಿದೆ ಅಥವಾ ತಪ್ಪಾಗಿ ಟೈಪ್ ಆಗಿದೆ ಎನಿಸುತ್ತದೆ. account.mapbox.com › Tokens ನಲ್ಲಿ ನಕಲು ಬಟನ್‌ನೊಂದಿಗೆ ಮತ್ತೆ ನಕಲಿಸಿ.",
        "Installed with AAEnabler: Update saves the new version to your Downloads, so you can install it with AAEnabler and keep it in Android Auto." to "AAEnabler ಮೂಲಕ ಸ್ಥಾಪಿಸಲಾಗಿದೆ: ನವೀಕರಿಸಿ ಹೊಸ ಆವೃತ್ತಿಯನ್ನು ನಿಮ್ಮ Downloads ಗೆ ಉಳಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ನೀವು ಅದನ್ನು AAEnabler ಮೂಲಕ ಸ್ಥಾಪಿಸಿ Android Auto ನಲ್ಲಿ ಇರಿಸಬಹುದು.",
        "Installed with AAEnabler (or similar)? Updating here takes it out of Android Auto: install the new version with AAEnabler again afterwards." to "AAEnabler (ಅಥವಾ ಅಂತಹದ್ದು) ಮೂಲಕ ಸ್ಥಾಪಿಸಲಾಗಿದೆಯೇ? ಇಲ್ಲಿ ನವೀಕರಿಸಿದರೆ ಅದು Android Auto ನಿಂದ ಹೊರಹೋಗುತ್ತದೆ: ನಂತರ ಹೊಸ ಆವೃತ್ತಿಯನ್ನು ಮತ್ತೆ AAEnabler ಮೂಲಕ ಸ್ಥಾಪಿಸಿ.",
        "{0} isn't working right now, so {1} is being used instead" to "{0} ಈಗ ಕೆಲಸ ಮಾಡುತ್ತಿಲ್ಲ, ಆದ್ದರಿಂದ ಬದಲಿಗೆ {1} ಬಳಸಲಾಗುತ್ತಿದೆ",
        "Mapbox refused the map for a moment, but your token is fine" to "Mapbox ಸ್ವಲ್ಪ ಸಮಯ ನಕ್ಷೆಯನ್ನು ನಿರಾಕರಿಸಿತು, ಆದರೆ ನಿಮ್ಮ ಟೋಕನ್ ಸರಿಯಾಗಿದೆ",
