        "Auto follows the head unit's own night mode once it has switched to it, and sunrise and sunset until then. Headlights follows the head unit's night mode when it switches with your lights (turn on its headlight or illumination night-mode option), with sun times until then. Sun times switches at sunrise and sunset. My times switches at the times you set" to "ಸ್ವಯಂ: ಹೆಡ್ ಯೂನಿಟ್ ತನ್ನದೇ ರಾತ್ರಿ ಮೋಡ್‌ಗೆ ಬದಲಾದ ನಂತರ ಅದನ್ನು ಅನುಸರಿಸುತ್ತದೆ, ಅಲ್ಲಿಯವರೆಗೆ ಸೂರ್ಯೋದಯ ಮತ್ತು ಸೂರ್ಯಾಸ್ತ. ಹೆಡ್‌ಲೈಟ್‌ಗಳು: ನಿಮ್ಮ ದೀಪಗಳೊಂದಿಗೆ ಬದಲಾದಾಗ ಹೆಡ್ ಯೂನಿಟ್‌ನ ರಾತ್ರಿ ಮೋಡ್ ಅನುಸರಿಸುತ್ತದೆ (ಅದರ ಹೆಡ್‌ಲೈಟ್ ಅಥವಾ ಇಲ್ಯುಮಿನೇಶನ್ ರಾತ್ರಿ-ಮೋಡ್ ಆಯ್ಕೆ ಆನ್ ಮಾಡಿ), ಅಲ್ಲಿಯವರೆಗೆ ಸೂರ್ಯನ ಸಮಯಗಳು. ಸೂರ್ಯನ ಸಮಯಗಳು: ಸೂರ್ಯೋದಯ ಮತ್ತು ಸೂರ್ಯಾಸ್ತದಲ್ಲಿ ಬದಲಾಗುತ್ತದೆ. ನನ್ನ ಸಮಯಗಳು: ನೀವು ಹೊಂದಿಸಿದ ಸಮಯಗಳಲ್ಲಿ ಬದಲಾಗುತ್ತದೆ",
