        "Grey lines with +/− minutes you can tap any time. Off shows a \"Faster route found\" card instead" to "ಯಾವಾಗ ಬೇಕಾದರೂ ಟ್ಯಾಪ್ ಮಾಡಬಹುದಾದ +/− ನಿಮಿಷಗಳೊಂದಿಗೆ ಬೂದು ಗೆರೆಗಳು. ಆಫ್ ಆದರೆ ಬದಲಿಗೆ \"ವೇಗದ ಮಾರ್ಗ ಸಿಕ್ಕಿದೆ\" ಕಾರ್ಡ್ ತೋರಿಸುತ್ತದೆ",
        "Suggest where you're going" to "ನೀವು ಎಲ್ಲಿಗೆ ಹೋಗುತ್ತೀರಿ ಎಂದು ಸೂಚಿಸಿ",
        "With the live journey time, including home and work at your usual times" to "ನೇರ ಪ್ರಯಾಣ ಸಮಯದೊಂದಿಗೆ, ನಿಮ್ಮ ಸಾಮಾನ್ಯ ಸಮಯಗಳಲ್ಲಿ ಮನೆ ಮತ್ತು ಕೆಲಸ ಸೇರಿ",
        "Weather on the route" to "ಮಾರ್ಗದ ಹವಾಮಾನ",
        "Arrive on your side of the road" to "ರಸ್ತೆಯ ನಿಮ್ಮ ಬದಿಯಲ್ಲಿ ತಲುಪಿ",
        "The route brings you to the kerb side of where you're going, so you don't have to cross the traffic. Mapbox and offline routes" to "ನೀವು ಹೋಗುವ ಸ್ಥಳದ ಫುಟ್‌ಪಾತ್ ಬದಿಗೆ ಮಾರ್ಗ ಕರೆದೊಯ್ಯುತ್ತದೆ, ಆದ್ದರಿಂದ ಟ್ರಾಫಿಕ್ ದಾಟಬೇಕಿಲ್ಲ. Mapbox ಮತ್ತು ಆಫ್‌ಲೈನ್ ಮಾರ್ಗಗಳು",
        "Starting a route" to "ಮಾರ್ಗ ಪ್ರಾರಂಭಿಸುವುದು",
