        "Vehicle" to "ವಾಹನ",
        "Used by TomTom and offline routes, and by Mapbox for height, width and weight. Limits come from the map data, so some may be missing: always follow the road signs." to "TomTom ಮತ್ತು ಆಫ್‌ಲೈನ್ ಮಾರ್ಗಗಳು ಬಳಸುತ್ತವೆ, ಮತ್ತು Mapbox ಎತ್ತರ, ಅಗಲ ಮತ್ತು ತೂಕಕ್ಕೆ. ಮಿತಿಗಳು ನಕ್ಷೆ ಡೇಟಾದಿಂದ ಬರುತ್ತವೆ, ಕೆಲವು ಇಲ್ಲದಿರಬಹುದು: ಯಾವಾಗಲೂ ರಸ್ತೆ ಫಲಕಗಳನ್ನು ಅನುಸರಿಸಿ.",
