        "Reset" to "ಮರುಹೊಂದಿಸಿ",
        "Turn card" to "ತಿರುವು ಕಾರ್ಡ್",
        "UK road signs on the turn card" to "ತಿರುವು ಕಾರ್ಡ್‌ನಲ್ಲಿ UK ರಸ್ತೆ ಫಲಕಗಳು",
        "Living turn card" to "ಜೀವಂತ ತಿರುವು ಕಾರ್ಡ್",
        "Grows and glows as the turn gets close" to "ತಿರುವು ಹತ್ತಿರವಾದಂತೆ ದೊಡ್ಡದಾಗಿ ಹೊಳೆಯುತ್ತದೆ",
        "Lane guidance on the turn card" to "ತಿರುವು ಕಾರ್ಡ್‌ನಲ್ಲಿ ಲೇನ್ ಮಾರ್ಗದರ್ಶನ",
        "Lane guidance style" to "ಲೇನ್ ಮಾರ್ಗದರ್ಶನದ ಶೈಲಿ",
