        "Junction pictures" to "ಜಂಕ್ಷನ್ ಚಿತ್ರಗಳು",
        "Mapbox's pictures of motorway junctions, with the lanes to use, in the last kilometre. Only where Mapbox has them, and only for Mapbox accounts it offers them to: if none ever show, yours doesn't have them" to "ಕೊನೆಯ ಕಿಲೋಮೀಟರ್‌ನಲ್ಲಿ, ಬಳಸಬೇಕಾದ ಲೇನ್‌ಗಳೊಂದಿಗೆ ಎಕ್ಸ್‌ಪ್ರೆಸ್‌ವೇ ಜಂಕ್ಷನ್‌ಗಳ Mapbox ಚಿತ್ರಗಳು. Mapbox ಬಳಿ ಇರುವಲ್ಲಿ ಮಾತ್ರ, ಮತ್ತು ಅವನ್ನು ನೀಡುವ Mapbox ಖಾತೆಗಳಿಗೆ ಮಾತ್ರ: ಎಂದಿಗೂ ಕಾಣಿಸದಿದ್ದರೆ, ನಿಮ್ಮ ಖಾತೆಗೆ ಅವು ಇಲ್ಲ",
        "Lanes on the map" to "ನಕ್ಷೆಯಲ್ಲಿ ಲೇನ್‌ಗಳು",
        "Lanes shown as" to "ಲೇನ್‌ಗಳನ್ನು ಹೀಗೆ ತೋರಿಸಲಾಗಿದೆ",
        "A drawn picture of the junction's lanes under the turn card for the last 400 m. Nothing drawn on the map" to "ಕೊನೆಯ 400 ಮೀ ಗೆ ತಿರುವು ಕಾರ್ಡ್‌ನ ಕೆಳಗೆ ಜಂಕ್ಷನ್ ಲೇನ್‌ಗಳ ಚಿತ್ರ. ನಕ್ಷೆಯಲ್ಲಿ ಏನೂ ಚಿತ್ರಿಸಲಾಗುವುದಿಲ್ಲ",
        "A sign over the road at the junction, with the lanes to use lit up" to "ಜಂಕ್ಷನ್‌ನಲ್ಲಿ ರಸ್ತೆಯ ಮೇಲೆ ಫಲಕ, ಬಳಸಬೇಕಾದ ಲೇನ್‌ಗಳು ಬೆಳಗಿರುತ್ತವೆ",
        "The lane to use lit up on the road. On motorways, where the real lanes are known, the route line moves into it" to "ಬಳಸಬೇಕಾದ ಲೇನ್ ರಸ್ತೆಯ ಮೇಲೆ ಬೆಳಗಿರುತ್ತದೆ. ಎಕ್ಸ್‌ಪ್ರೆಸ್‌ವೇಗಳಲ್ಲಿ, ನಿಜವಾದ ಲೇನ್‌ಗಳು ತಿಳಿದಿರುವಲ್ಲಿ, ಮಾರ್ಗದ ಗೆರೆ ಅದರೊಳಗೆ ಸರಿಯುತ್ತದೆ",
        "Lit lane" to "ಬೆಳಗಿದ ಲೇನ್",
