        "Other screens" to "ಇತರ ಪರದೆಗಳು",
        "Next turn in the notification" to "ಅಧಿಸೂಚನೆಯಲ್ಲಿ ಮುಂದಿನ ತಿರುವು",
        "The arrow, distance and road in Horizon Nav's notification while you navigate, for car launchers, watches and other screens that show navigation notifications" to "ನೀವು ನ್ಯಾವಿಗೇಟ್ ಮಾಡುವಾಗ Horizon Nav ಅಧಿಸೂಚನೆಯಲ್ಲಿ ಬಾಣ, ದೂರ ಮತ್ತು ರಸ್ತೆ, ನ್ಯಾವಿಗೇಶನ್ ಅಧಿಸೂಚನೆಗಳನ್ನು ತೋರಿಸುವ ಕಾರ್ ಲಾಂಚರ್‌ಗಳು, ಕೈಗಡಿಯಾರಗಳು ಮತ್ತು ಇತರ ಪರದೆಗಳಿಗಾಗಿ",
