        "Next speed limit ahead" to "ಮುಂದಿನ ವೇಗ ಮಿತಿ",
        "A small sign above the limit with the next one on your route and how far it is, from about half a mile away" to "ಮಿತಿಯ ಮೇಲೆ ಚಿಕ್ಕ ಫಲಕ, ನಿಮ್ಮ ಮಾರ್ಗದ ಮುಂದಿನದು ಮತ್ತು ಅದು ಎಷ್ಟು ದೂರ ಎಂದು, ಸುಮಾರು ಅರ್ಧ ಮೈಲಿ ಮೊದಲಿನಿಂದ",
        "Show estimated limits" to "ಅಂದಾಜು ಮಿತಿಗಳನ್ನು ತೋರಿಸಿ",
