        "Default zoom" to "ಡೀಫಾಲ್ಟ್ ಜೂಮ್",
        "When you're not on a route. Auto zoom still pulls out at speed and moves in at junctions, round your setting. Or zoom with + and − on the map and tap \"Make this my default\"" to "ನೀವು ಮಾರ್ಗದಲ್ಲಿ ಇಲ್ಲದಿದ್ದಾಗ. ಸ್ವಯಂ ಜೂಮ್ ವೇಗದಲ್ಲಿ ಹೊರಗೆ ಮತ್ತು ಜಂಕ್ಷನ್‌ಗಳಲ್ಲಿ ಒಳಗೆ ಸರಿಯುತ್ತದೆ, ನಿಮ್ಮ ಸೆಟ್ಟಿಂಗ್‌ನ ಸುತ್ತ. ಅಥವಾ ನಕ್ಷೆಯಲ್ಲಿ + ಮತ್ತು − ನಿಂದ ಜೂಮ್ ಮಾಡಿ \"ಇದನ್ನು ನನ್ನ ಡೀಫಾಲ್ಟ್ ಮಾಡಿ\" ಟ್ಯಾಪ್ ಮಾಡಿ",
