        "Pair once: on the head unit, tap Pair a phone and type its code into Horizon Nav on your phone (in this same place). Then \"Send to car\" on the phone's route screen sends the place to the head unit, which starts it the next time it's on (within 12 hours). Places go through ntfy.sh, a free message relay, scrambled with your code so only your phone and car can read them." to "ಒಮ್ಮೆ ಜೋಡಿಸಿ: ಹೆಡ್ ಯೂನಿಟ್‌ನಲ್ಲಿ, ಫೋನ್ ಜೋಡಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ ಮತ್ತು ಅದರ ಕೋಡ್ ಅನ್ನು ನಿಮ್ಮ ಫೋನ್‌ನ Horizon Nav ನಲ್ಲಿ (ಇದೇ ಸ್ಥಳದಲ್ಲಿ) ಟೈಪ್ ಮಾಡಿ. ನಂತರ ಫೋನ್‌ನ ಮಾರ್ಗ ಪರದೆಯಲ್ಲಿನ \"ಕಾರಿಗೆ ಕಳುಹಿಸಿ\" ಸ್ಥಳವನ್ನು ಹೆಡ್ ಯೂನಿಟ್‌ಗೆ ಕಳುಹಿಸುತ್ತದೆ, ಅದು ಮುಂದಿನ ಬಾರಿ ಆನ್ ಆದಾಗ (12 ಗಂಟೆಗಳೊಳಗೆ) ಪ್ರಾರಂಭಿಸುತ್ತದೆ. ಸ್ಥಳಗಳು ಉಚಿತ ಸಂದೇಶ ರಿಲೇ ntfy.sh ಮೂಲಕ ಹೋಗುತ್ತವೆ, ನಿಮ್ಮ ಕೋಡ್‌ನಿಂದ ಗೂಢಗೊಳಿಸಲಾಗಿದೆ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ಫೋನ್ ಮತ್ತು ಕಾರು ಮಾತ್ರ ಓದಬಹುದು.",
        "This is the car" to "ಇದು ಕಾರು",
