        "The share button on the trip card texts your arrival time and a map link. On a head unit without a SIM it opens your messaging app instead." to "ಪ್ರಯಾಣ ಕಾರ್ಡ್‌ನ ಹಂಚಿಕೆ ಬಟನ್ ನಿಮ್ಮ ತಲುಪುವ ಸಮಯ ಮತ್ತು ನಕ್ಷೆ ಲಿಂಕ್ ಅನ್ನು SMS ಮಾಡುತ್ತದೆ. SIM ಇಲ್ಲದ ಹೆಡ್ ಯೂನಿಟ್‌ನಲ್ಲಿ ಬದಲಿಗೆ ನಿಮ್ಮ ಸಂದೇಶ ಆ್ಯಪ್ ತೆರೆಯುತ್ತದೆ.",
        "Send it to" to "ಇವರಿಗೆ ಕಳುಹಿಸಿ",
        "No one chosen yet" to "ಇನ್ನೂ ಯಾರನ್ನೂ ಆರಿಸಿಲ್ಲ",
        "Places from other apps" to "ಇತರ ಆ್ಯಪ್‌ಗಳಿಂದ ಸ್ಥಳಗಳು",
        "Share a place to Horizon Nav from Google Maps, WhatsApp, Contacts or a web page and it plans the route. To open Google Maps links here straight away, tap Open by default and add the links." to "Google Maps, WhatsApp, ಸಂಪರ್ಕಗಳು ಅಥವಾ ವೆಬ್ ಪುಟದಿಂದ Horizon Nav ಗೆ ಸ್ಥಳವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ, ಅದು ಮಾರ್ಗ ಯೋಜಿಸುತ್ತದೆ. Google Maps ಲಿಂಕ್‌ಗಳನ್ನು ನೇರವಾಗಿ ಇಲ್ಲಿ ತೆರೆಯಲು, ಡೀಫಾಲ್ಟ್ ಆಗಿ ತೆರೆಯಿರಿ ಟ್ಯಾಪ್ ಮಾಡಿ ಲಿಂಕ್‌ಗಳನ್ನು ಸೇರಿಸಿ.",
        "Google Maps links" to "Google Maps ಲಿಂಕ್‌ಗಳು",
        "Open by default" to "ಡೀಫಾಲ್ಟ್ ಆಗಿ ತೆರೆಯಿರಿ",
        "Fuel prices" to "ಇಂಧನ ಬೆಲೆಗಳು",
        "Live prices come from the government's Fuel Finder scheme. It's free: on gov.uk search \"Fuel Finder\", register as an information recipient with a GOV.UK One Login, then paste the client ID and secret here. Without them the fuel list still works, just without prices." to "ನೇರ ಬೆಲೆಗಳು UK ಸರ್ಕಾರದ Fuel Finder ಯೋಜನೆಯಿಂದ ಬರುತ್ತವೆ. ಇದು ಉಚಿತ: gov.uk ನಲ್ಲಿ \"Fuel Finder\" ಹುಡುಕಿ, GOV.UK One Login ನೊಂದಿಗೆ ಮಾಹಿತಿ ಸ್ವೀಕರಿಸುವವರಾಗಿ ನೋಂದಾಯಿಸಿ, ನಂತರ ಕ್ಲೈಂಟ್ ID ಮತ್ತು ರಹಸ್ಯವನ್ನು ಇಲ್ಲಿ ಅಂಟಿಸಿ. ಅವುಗಳಿಲ್ಲದೆ ಇಂಧನ ಪಟ್ಟಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ, ಬೆಲೆಗಳಿಲ್ಲದೆ.",
        "Your fuel" to "ನಿಮ್ಮ ಇಂಧನ",
        "Unleaded" to "ಅನ್‌ಲೆಡೆಡ್",
        "Super" to "ಸೂಪರ್",
