        "Suggest a fuel stop on long trips" to "ದೀರ್ಘ ಪ್ರಯಾಣಗಳಲ್ಲಿ ಇಂಧನ ನಿಲುಗಡೆ ಸೂಚಿಸಿ",
        "Over about 95 miles" to "ಸುಮಾರು 95 ಮೈಲಿಗಿಂತ ಹೆಚ್ಚು",
