        ", the best-value station along the way" to ", ದಾರಿಯಲ್ಲಿನ ಅತ್ಯುತ್ತಮ ಮೌಲ್ಯದ ಬಂಕ್",
        "Client ID" to "ಕ್ಲೈಂಟ್ ID",
        "Client secret" to "ಕ್ಲೈಂಟ್ ರಹಸ್ಯ",
        "Prices" to "ಬೆಲೆಗಳು",
