        "Update now" to "ಈಗ ನವೀಕರಿಸಿ",
        "Downloading stations and prices (the first time takes a minute)…" to "ಬಂಕ್‌ಗಳು ಮತ್ತು ಬೆಲೆಗಳನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡುತ್ತಿದೆ (ಮೊದಲ ಬಾರಿ ಒಂದು ನಿಮಿಷ ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ)…",
        "Spotted a wrong price?" to "ತಪ್ಪು ಬೆಲೆ ಕಂಡಿತೇ?",
        "Report it" to "ವರದಿ ಮಾಡಿ",
        "Fuel prices outside the UK" to "UK ಹೊರಗಿನ ಇಂಧನ ಬೆಲೆಗಳು",
        "France and Austria work by themselves, from their governments' own price services. Germany needs a free key from creativecommons.tankerkoenig.de (Tankerkönig). Australia (NSW and Tasmania) needs a free API key and secret from api.nsw.gov.au (Fuel API). Prices show in cents a litre, e.g. 189.9c. Elsewhere the fuel list still works, without prices." to "ಫ್ರಾನ್ಸ್ ಮತ್ತು ಆಸ್ಟ್ರಿಯಾ ತಾವಾಗಿಯೇ ಕೆಲಸ ಮಾಡುತ್ತವೆ, ಅವುಗಳ ಸರ್ಕಾರಗಳ ಸ್ವಂತ ಬೆಲೆ ಸೇವೆಗಳಿಂದ. ಜರ್ಮನಿಗೆ creativecommons.tankerkoenig.de (Tankerkönig) ನಿಂದ ಉಚಿತ ಕೀ ಬೇಕು. ಆಸ್ಟ್ರೇಲಿಯಾಗೆ (NSW ಮತ್ತು ಟ್ಯಾಸ್ಮೇನಿಯಾ) api.nsw.gov.au (Fuel API) ನಿಂದ ಉಚಿತ API ಕೀ ಮತ್ತು ರಹಸ್ಯ ಬೇಕು. ಬೆಲೆಗಳು ಲೀಟರ್‌ಗೆ ಸೆಂಟ್‌ಗಳಲ್ಲಿ ತೋರಿಸುತ್ತವೆ, ಉದಾ. 189.9c. ಬೇರೆಡೆ ಇಂಧನ ಪಟ್ಟಿ ಬೆಲೆಗಳಿಲ್ಲದೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ.",
        "Tankerkönig key (Germany)" to "Tankerkönig ಕೀ (ಜರ್ಮನಿ)",
        "Paste the key" to "ಕೀ ಅಂಟಿಸಿ",
        "FuelCheck API key (Australia)" to "FuelCheck API ಕೀ (ಆಸ್ಟ್ರೇಲಿಯಾ)",
        "New South Wales and Tasmania" to "ನ್ಯೂ ಸೌತ್ ವೇಲ್ಸ್ ಮತ್ತು ಟ್ಯಾಸ್ಮೇನಿಯಾ",
        "Paste the API key" to "API ಕೀ ಅಂಟಿಸಿ",
        "FuelCheck API secret" to "FuelCheck API ರಹಸ್ಯ",
        "Paste the API secret" to "API ರಹಸ್ಯ ಅಂಟಿಸಿ",
        "Your electric car" to "ನಿಮ್ಮ ವಿದ್ಯುತ್ ಕಾರು",
        "With the efficiency and price filled in, each route shows roughly what it will cost to charge for. The efficiency and battery size also give the battery estimate on the trip card and the charging stop suggestions (set your battery level on the route options)." to "ದಕ್ಷತೆ ಮತ್ತು ಬೆಲೆ ತುಂಬಿದರೆ, ಪ್ರತಿ ಮಾರ್ಗ ಚಾರ್ಜ್ ಮಾಡಲು ಸರಿಸುಮಾರು ಎಷ್ಟು ವೆಚ್ಚವಾಗುತ್ತದೆ ಎಂದು ತೋರಿಸುತ್ತದೆ. ದಕ್ಷತೆ ಮತ್ತು ಬ್ಯಾಟರಿ ಗಾತ್ರ ಪ್ರಯಾಣ ಕಾರ್ಡ್‌ನ ಬ್ಯಾಟರಿ ಅಂದಾಜು ಮತ್ತು ಚಾರ್ಜಿಂಗ್ ನಿಲುಗಡೆ ಸಲಹೆಗಳನ್ನೂ ನೀಡುತ್ತವೆ (ಮಾರ್ಗದ ಆಯ್ಕೆಗಳಲ್ಲಿ ನಿಮ್ಮ ಬ್ಯಾಟರಿ ಮಟ್ಟ ಹೊಂದಿಸಿ).",
        "Battery estimate on the trip card" to "ಪ್ರಯಾಣ ಕಾರ್ಡ್‌ನಲ್ಲಿ ಬ್ಯಾಟರಿ ಅಂದಾಜು",
        "Roughly how much battery you'll arrive with, on the phone and Android Auto. It's worked out from your settings, not read from the car" to "ಫೋನ್ ಮತ್ತು Android Auto ನಲ್ಲಿ, ನೀವು ಸರಿಸುಮಾರು ಎಷ್ಟು ಬ್ಯಾಟರಿಯೊಂದಿಗೆ ತಲುಪುತ್ತೀರಿ. ಇದನ್ನು ನಿಮ್ಮ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ, ಕಾರಿನಿಂದ ಓದುವುದಿಲ್ಲ",
        "Show petrol stations too" to "ಪೆಟ್ರೋಲ್ ಬಂಕ್‌ಗಳನ್ನೂ ತೋರಿಸಿ",
        "The Fuel button on the map page (on the phone and Android Auto). Off: Charging takes its place" to "ನಕ್ಷೆ ಪುಟದಲ್ಲಿನ ಇಂಧನ ಬಟನ್ (ಫೋನ್ ಮತ್ತು Android Auto ನಲ್ಲಿ). ಆಫ್: ಚಾರ್ಜಿಂಗ್ ಅದರ ಸ್ಥಾನ ಪಡೆಯುತ್ತದೆ",
        "Efficiency (miles per kWh)" to "ದಕ್ಷತೆ (ಪ್ರತಿ kWh ಗೆ ಮೈಲಿ)",
        "e.g. 3.5" to "ಉದಾ. 3.5",
        "Efficiency (km per kWh)" to "ದಕ್ಷತೆ (ಪ್ರತಿ kWh ಗೆ ಕಿಮೀ)",
        "e.g. 5.6" to "ಉದಾ. 5.6",
