        "On this screen (Android Auto has its own size, under Android Auto)" to "ಈ ಪರದೆಯಲ್ಲಿ (Android Auto ಗೆ ತನ್ನದೇ ಗಾತ್ರವಿದೆ, Android Auto ಅಡಿಯಲ್ಲಿ)",
        "Speed position" to "ವೇಗದ ಸ್ಥಾನ",
