        "Automatic follows the phone's or head unit's own 12 / 24-hour setting" to "ಸ್ವಯಂಚಾಲಿತ ಎಂದರೆ ಫೋನ್ ಅಥವಾ ಹೆಡ್ ಯೂನಿಟ್‌ನ ಸ್ವಂತ 12 / 24-ಗಂಟೆ ಸೆಟ್ಟಿಂಗ್ ಅನುಸರಿಸುತ್ತದೆ",
