        "Left-hand drive" to "ಎಡಗೈ ಚಾಲನೆ",
        "Driver on the right (UK): cards on the left, buttons on the right" to "ಚಾಲಕ ಬಲಭಾಗದಲ್ಲಿ (UK, ಭಾರತ): ಕಾರ್ಡ್‌ಗಳು ಎಡಕ್ಕೆ, ಬಟನ್‌ಗಳು ಬಲಕ್ಕೆ",
        "Driver on the left (US, Europe): the screen is mirrored, cards on the right" to "ಚಾಲಕ ಎಡಭಾಗದಲ್ಲಿ (US, ಯುರೋಪ್): ಪರದೆ ಪ್ರತಿಬಿಂಬಿತ, ಕಾರ್ಡ್‌ಗಳು ಬಲಕ್ಕೆ",
        "Follows the country you're in" to "ನೀವಿರುವ ದೇಶವನ್ನು ಅನುಸರಿಸುತ್ತದೆ",
        ": left-hand drive, screen mirrored" to ": ಎಡಗೈ ಚಾಲನೆ, ಪರದೆ ಪ್ರತಿಬಿಂಬಿತ",
        ": right-hand drive" to ": ಬಲಗೈ ಚಾಲನೆ",
        "Google Play (Android Auto lists it without any extra steps)" to "Google Play (Android Auto ಯಾವುದೇ ಹೆಚ್ಚುವರಿ ಹಂತಗಳಿಲ್ಲದೆ ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ)",
        "Unknown (installed from a file): needs Unknown sources in Android Auto" to "ಅಜ್ಞಾತ (ಫೈಲ್‌ನಿಂದ ಸ್ಥಾಪಿಸಲಾಗಿದೆ): Android Auto ನಲ್ಲಿ ಅಜ್ಞಾತ ಮೂಲಗಳು ಬೇಕು",
        "Horizon Nav's own updater: needs Unknown sources in Android Auto" to "Horizon Nav ನ ಸ್ವಂತ ಅಪ್‌ಡೇಟರ್: Android Auto ನಲ್ಲಿ ಅಜ್ಞಾತ ಮೂಲಗಳು ಬೇಕು",
        "{0}: needs Unknown sources in Android Auto" to "{0}: Android Auto ನಲ್ಲಿ ಅಜ್ಞಾತ ಮೂಲಗಳು ಬೇಕು",
        "Unknown" to "ಅಜ್ಞಾತ",
        "Sizes on the car screen" to "ಕಾರಿನ ಪರದೆಯಲ್ಲಿ ಗಾತ್ರಗಳು",
        "Overall size on the car screen" to "ಕಾರಿನ ಪರದೆಯಲ್ಲಿ ಒಟ್ಟು ಗಾತ್ರ",
        "Base scale for the whole overlay" to "ಸಂಪೂರ್ಣ ಓವರ್‌ಲೇಗೆ ಮೂಲ ಅಳತೆ",
        "Speedometer and speed-limit sign size" to "ಸ್ಪೀಡೋಮೀಟರ್ ಮತ್ತು ವೇಗ ಮಿತಿ ಫಲಕದ ಗಾತ್ರ",
        "Automatically shrinks further if the available screen area is too small" to "ಲಭ್ಯವಿರುವ ಪರದೆಯ ಸ್ಥಳ ತುಂಬಾ ಚಿಕ್ಕದಾಗಿದ್ದರೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಇನ್ನಷ್ಟು ಚಿಕ್ಕದಾಗುತ್ತದೆ",
        "Speed position on the car screen" to "ಕಾರಿನ ಪರದೆಯಲ್ಲಿ ವೇಗದ ಸ್ಥಾನ",
        "On the side away from the cards. Separate from this screen's own setting" to "ಕಾರ್ಡ್‌ಗಳಿಂದ ದೂರದ ಬದಿಯಲ್ಲಿ. ಈ ಪರದೆಯ ಸ್ವಂತ ಸೆಟ್ಟಿಂಗ್‌ನಿಂದ ಪ್ರತ್ಯೇಕ",
        "Advanced car-screen sizes" to "ಸುಧಾರಿತ ಕಾರಿನ ಪರದೆ ಗಾತ್ರಗಳು",
        "Fine-tune individual elements independently" to "ಪ್ರತ್ಯೇಕ ಅಂಶಗಳನ್ನು ಸ್ವತಂತ್ರವಾಗಿ ಸರಿಹೊಂದಿಸಿ",
        "Round controls and tappable buttons" to "ವೃತ್ತಾಕಾರ ನಿಯಂತ್ರಣಗಳು ಮತ್ತು ಟ್ಯಾಪ್ ಮಾಡುವ ಬಟನ್‌ಗಳು",
        "Independent of card and button sizing" to "ಕಾರ್ಡ್ ಮತ್ತು ಬಟನ್ ಗಾತ್ರದಿಂದ ಸ್ವತಂತ್ರ",
        "Setting it up" to "ಅದನ್ನು ಹೊಂದಿಸುವುದು",
        "If Horizon Nav doesn't appear in Android Auto: 1. Open Android Auto's settings, tap the version number at the bottom about 10 times, then in the top-right menu open Developer settings and turn on Unknown sources. 2. Back in Android Auto's settings, open Customise launcher and make sure Horizon Nav is ticked. 3. Force stop Android Auto (App info below), unplug and plug back in. If it still doesn't show, your phone's Android Auto only lists apps installed by the Play Store: install the APK through an installer that sets Play as the source (for example \"adb install -i com.android.vending\", or an app like AAAD or Install with Options)." to "Horizon Nav Android Auto ನಲ್ಲಿ ಕಾಣಿಸದಿದ್ದರೆ: 1. Android Auto ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ, ಕೆಳಗಿನ ಆವೃತ್ತಿ ಸಂಖ್ಯೆಯನ್ನು ಸುಮಾರು 10 ಬಾರಿ ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ ಮೇಲಿನ ಬಲ ಮೆನುವಿನಲ್ಲಿ ಡೆವಲಪರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ತೆರೆದು ಅಜ್ಞಾತ ಮೂಲಗಳನ್ನು ಆನ್ ಮಾಡಿ. 2. Android Auto ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಮರಳಿ, ಲಾಂಚರ್ ಕಸ್ಟಮೈಸ್ ತೆರೆದು Horizon Nav ಟಿಕ್ ಆಗಿದೆಯೇ ಎಂದು ಖಚಿತಪಡಿಸಿ. 3. Android Auto ಅನ್ನು ಬಲವಂತವಾಗಿ ನಿಲ್ಲಿಸಿ (ಕೆಳಗಿನ ಆ್ಯಪ್ ಮಾಹಿತಿ), ಅನ್‌ಪ್ಲಗ್ ಮಾಡಿ ಮತ್ತೆ ಪ್ಲಗ್ ಮಾಡಿ. ಇನ್ನೂ ಕಾಣಿಸದಿದ್ದರೆ, ನಿಮ್ಮ ಫೋನ್‌ನ Android Auto Play Store ಸ್ಥಾಪಿಸಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ಮಾತ್ರ ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ: Play ಅನ್ನು ಮೂಲವಾಗಿ ಹೊಂದಿಸುವ ಸ್ಥಾಪಕದ ಮೂಲಕ APK ಸ್ಥಾಪಿಸಿ (ಉದಾಹರಣೆಗೆ \"adb install -i com.android.vending\", ಅಥವಾ AAAD ಅಥವಾ Install with Options ನಂತಹ ಆ್ಯಪ್).",
        "Installed by" to "ಸ್ಥಾಪಿಸಿದವರು",
        "Android Auto settings" to "Android Auto ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
        "Android Auto isn't installed on this phone" to "ಈ ಫೋನ್‌ನಲ್ಲಿ Android Auto ಸ್ಥಾಪಿತವಾಗಿಲ್ಲ",
        "Android Auto app info" to "Android Auto ಆ್ಯಪ್ ಮಾಹಿತಿ",
        "To force stop it after changing its settings" to "ಅದರ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬದಲಾಯಿಸಿದ ನಂತರ ಬಲವಂತವಾಗಿ ನಿಲ್ಲಿಸಲು",
        "App info" to "ಆ್ಯಪ್ ಮಾಹಿತಿ",
        "Not showing in Android Auto?" to "Android Auto ನಲ್ಲಿ ಕಾಣಿಸುತ್ತಿಲ್ಲವೇ?",
        "1. In Android Auto's settings, tap Version repeatedly to unlock Developer settings, then turn on Unknown sources. " to "1. Android Auto ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ, ಡೆವಲಪರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು ಆವೃತ್ತಿಯನ್ನು ಪದೇ ಪದೇ ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ ಅಜ್ಞಾತ ಮೂಲಗಳನ್ನು ಆನ್ ಮಾಡಿ. ",
        "2. Force stop Android Auto (App info above) and reconnect. 3. If it still isn't listed, install Horizon Nav with the free AAEnabler app, which most people need. " to "2. Android Auto ಅನ್ನು ಬಲವಂತವಾಗಿ ನಿಲ್ಲಿಸಿ (ಮೇಲಿನ ಆ್ಯಪ್ ಮಾಹಿತಿ) ಮತ್ತು ಮತ್ತೆ ಸಂಪರ್ಕಿಸಿ. 3. ಇನ್ನೂ ಪಟ್ಟಿಯಲ್ಲಿ ಇಲ್ಲದಿದ್ದರೆ, ಉಚಿತ AAEnabler ಆ್ಯಪ್ ಮೂಲಕ Horizon Nav ಸ್ಥಾಪಿಸಿ, ಹೆಚ್ಚಿನವರಿಗೆ ಇದು ಬೇಕಾಗುತ್ತದೆ. ",
        "Voice requests through Android Auto's own microphone may not reach apps from outside Google Play: use the app's search button instead." to "Android Auto ನ ಸ್ವಂತ ಮೈಕ್ರೊಫೋನ್ ಮೂಲಕ ಧ್ವನಿ ವಿನಂತಿಗಳು Google Play ಹೊರಗಿನ ಆ್ಯಪ್‌ಗಳನ್ನು ತಲುಪದಿರಬಹುದು: ಬದಲಿಗೆ ಆ್ಯಪ್‌ನ ಹುಡುಕಾಟ ಬಟನ್ ಬಳಸಿ.",
        "No browser on this device: search for AAEnabler on GitHub" to "ಈ ಸಾಧನದಲ್ಲಿ ಬ್ರೌಸರ್ ಇಲ್ಲ: GitHub ನಲ್ಲಿ AAEnabler ಹುಡುಕಿ",
        "Smoothness" to "ಸುಗಮತೆ",
        "Lower these if the map feels slow or the head unit gets warm. Sharpness and fast drawing apply after restarting the app." to "ನಕ್ಷೆ ನಿಧಾನವೆನಿಸಿದರೆ ಅಥವಾ ಹೆಡ್ ಯೂನಿಟ್ ಬಿಸಿಯಾದರೆ ಇವುಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಿ. ತೀಕ್ಷ್ಣತೆ ಮತ್ತು ವೇಗದ ಚಿತ್ರಣ ಆ್ಯಪ್ ಮರುಪ್ರಾರಂಭದ ನಂತರ ಅನ್ವಯಿಸುತ್ತವೆ.",
        "Map sharpness" to "ನಕ್ಷೆಯ ತೀಕ್ಷ್ಣತೆ",
        "Full" to "ಪೂರ್ಣ",
        "Balanced" to "ಸಮತೋಲಿತ",
        "Light" to "ಹಗುರ",
        "Lowest" to "ಅತಿ ಕಡಿಮೆ",
        "Frame rate" to "ಫ್ರೇಮ್ ದರ",
        "Starts at 30 and steps down when the head unit can't keep up, so the map moves evenly" to "30 ರಿಂದ ಪ್ರಾರಂಭವಾಗಿ ಹೆಡ್ ಯೂನಿಟ್ ಹಿಂದೆ ಬಿದ್ದಾಗ ಕಡಿಮೆಯಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ನಕ್ಷೆ ಸಮವಾಗಿ ಚಲಿಸುತ್ತದೆ",
        "Lower is lighter on the head unit" to "ಕಡಿಮೆಯಾದಷ್ಟು ಹೆಡ್ ಯೂನಿಟ್‌ಗೆ ಹಗುರ",
        "Fast map drawing" to "ವೇಗದ ನಕ್ಷೆ ಚಿತ್ರಣ",
        "Performance meter" to "ಕಾರ್ಯಕ್ಷಮತೆ ಮೀಟರ್",
        "A line at the top of the map: frames drawn, camera moves and pauses. Handy for finding what slows the map" to "ನಕ್ಷೆಯ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಒಂದು ಸಾಲು: ಚಿತ್ರಿಸಿದ ಫ್ರೇಮ್‌ಗಳು, ಕ್ಯಾಮೆರಾ ಚಲನೆಗಳು ಮತ್ತು ವಿರಾಮಗಳು. ನಕ್ಷೆಯನ್ನು ಏನು ನಿಧಾನಗೊಳಿಸುತ್ತದೆ ಎಂದು ಕಂಡುಹಿಡಿಯಲು ಉಪಯುಕ್ತ",
        "Demo" to "ಡೆಮೊ",
        "Demo drive button" to "ಡೆಮೊ ಚಾಲನೆ ಬಟನ್",
        "Plays a route back so you can try the guidance while parked" to "ಪಾರ್ಕ್ ಮಾಡಿರುವಾಗ ಮಾರ್ಗದರ್ಶನ ಪ್ರಯತ್ನಿಸಲು ಮಾರ್ಗವನ್ನು ಪ್ಲೇ ಮಾಡುತ್ತದೆ",
        "Search results" to "ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳು",
        "Search with" to "ಇದರೊಂದಿಗೆ ಹುಡುಕಿ",
        "TomTom's search is the one Horizon Nav uses: best for UK addresses and house numbers" to "Horizon Nav ಬಳಸುವುದು TomTom ಹುಡುಕಾಟ: UK ವಿಳಾಸಗಳು ಮತ್ತು ಮನೆ ಸಂಖ್ಯೆಗಳಿಗೆ ಅತ್ಯುತ್ತಮ",
        "For the most accurate address search, add a free TomTom key below." to "ಅತ್ಯಂತ ನಿಖರ ವಿಳಾಸ ಹುಡುಕಾಟಕ್ಕೆ, ಕೆಳಗೆ ಉಚಿತ TomTom ಕೀ ಸೇರಿಸಿ.",
        "Map accounts" to "ನಕ್ಷೆ ಖಾತೆಗಳು",
        "Search also finds places you saved or went to before. With no signal, routes, the map and search come from the offline pack." to "ನೀವು ಉಳಿಸಿದ ಅಥವಾ ಮೊದಲು ಹೋದ ಸ್ಥಳಗಳನ್ನೂ ಹುಡುಕಾಟ ಕಂಡುಹಿಡಿಯುತ್ತದೆ. ಸಿಗ್ನಲ್ ಇಲ್ಲದಿದ್ದರೆ, ಮಾರ್ಗಗಳು, ನಕ್ಷೆ ಮತ್ತು ಹುಡುಕಾಟ ಆಫ್‌ಲೈನ್ ಪ್ಯಾಕ್‌ನಿಂದ ಬರುತ್ತವೆ.",
        "TomTom API key" to "TomTom API ಕೀ",
        "Using the key built into this app unless you paste another" to "ನೀವು ಬೇರೊಂದನ್ನು ಅಂಟಿಸದಿದ್ದರೆ ಈ ಆ್ಯಪ್‌ನೊಳಗಿನ ಕೀ ಬಳಸುತ್ತಿದೆ",
        "Optional: gives the most accurate address search, and a backup for routes and traffic. Free from developer.tomtom.com" to "ಐಚ್ಛಿಕ: ಅತ್ಯಂತ ನಿಖರ ವಿಳಾಸ ಹುಡುಕಾಟ ಮತ್ತು ಮಾರ್ಗಗಳು ಹಾಗೂ ಟ್ರಾಫಿಕ್‌ಗೆ ಬ್ಯಾಕಪ್ ನೀಡುತ್ತದೆ. developer.tomtom.com ನಿಂದ ಉಚಿತ",
        "Paste a key" to "ಕೀ ಅಂಟಿಸಿ",
