        "Custom" to "ಕಸ್ಟಮ್",
        "Horizon: Mapbox's map in the app's own soft colours, slate blue at night. Twilight: the same with a deeper purple night. Mono Night: greys, with only the route and warnings in colour. Match my car: a hint of your car's interior lighting colour. Custom: your own colours. Day colours shown (Match my car at night); each has a night version" to "Horizon: ಆ್ಯಪ್‌ನ ಸ್ವಂತ ಮೃದು ಬಣ್ಣಗಳಲ್ಲಿ Mapbox ನಕ್ಷೆ, ರಾತ್ರಿ ಸ್ಲೇಟ್ ನೀಲಿ. Twilight: ಅದೇ, ಆಳವಾದ ನೇರಳೆ ರಾತ್ರಿಯೊಂದಿಗೆ. ಮೊನೊ ರಾತ್ರಿ: ಬೂದು ಬಣ್ಣಗಳು, ಮಾರ್ಗ ಮತ್ತು ಎಚ್ಚರಿಕೆಗಳು ಮಾತ್ರ ಬಣ್ಣದಲ್ಲಿ. ನನ್ನ ಕಾರಿಗೆ ಹೊಂದಿಸಿ: ನಿಮ್ಮ ಕಾರಿನ ಒಳಬೆಳಕಿನ ಬಣ್ಣದ ಸ್ವಲ್ಪ ಛಾಯೆ. ಕಸ್ಟಮ್: ನಿಮ್ಮ ಸ್ವಂತ ಬಣ್ಣಗಳು. ಹಗಲಿನ ಬಣ್ಣಗಳನ್ನು ತೋರಿಸಲಾಗಿದೆ (ನನ್ನ ಕಾರಿಗೆ ಹೊಂದಿಸಿ ರಾತ್ರಿಯಲ್ಲಿ); ಪ್ರತಿಯೊಂದಕ್ಕೂ ರಾತ್ರಿ ಆವೃತ್ತಿ ಇದೆ",
        "Live preview" to "ನೇರ ಮುನ್ನೋಟ",
        "Custom colours" to "ಕಸ್ಟಮ್ ಬಣ್ಣಗಳು",
        "Changes show on the preview at the top as you make them, and are only kept when you press Save. A part you haven't changed keeps the colour of the theme it starts from. At night the light darkens the colours you pick, as it does every theme." to "ಬದಲಾವಣೆಗಳು ಮಾಡುತ್ತಿದ್ದಂತೆ ಮೇಲಿನ ಮುನ್ನೋಟದಲ್ಲಿ ಕಾಣುತ್ತವೆ, ಮತ್ತು ಉಳಿಸಿ ಒತ್ತಿದಾಗ ಮಾತ್ರ ಉಳಿಯುತ್ತವೆ. ನೀವು ಬದಲಾಯಿಸದ ಭಾಗ ಅದು ಪ್ರಾರಂಭವಾಗುವ ಥೀಮ್‌ನ ಬಣ್ಣ ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ. ರಾತ್ರಿ ಬೆಳಕು ನೀವು ಆರಿಸುವ ಬಣ್ಣಗಳನ್ನು ಗಾಢಗೊಳಿಸುತ್ತದೆ, ಎಲ್ಲಾ ಥೀಮ್‌ಗಳಂತೆ.",
