        "Back" to "ಹಿಂದೆ",
        "Get started" to "ಪ್ರಾರಂಭಿಸಿ",
        "Next" to "ಮುಂದೆ",
        "Start driving" to "ಚಾಲನೆ ಪ್ರಾರಂಭಿಸಿ",
        "Horizon Nav is built for the car: big, clear guidance on Mapbox's 3D map, with live traffic, UK speed limits and cameras, and routes and search that keep working with no signal." to "Horizon Nav ಕಾರಿಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ: Mapbox ನ 3D ನಕ್ಷೆಯಲ್ಲಿ ದೊಡ್ಡ, ಸ್ಪಷ್ಟ ಮಾರ್ಗದರ್ಶನ, ನೇರ ಟ್ರಾಫಿಕ್, UK ವೇಗ ಮಿತಿಗಳು ಮತ್ತು ಕ್ಯಾಮೆರಾಗಳೊಂದಿಗೆ, ಮತ್ತು ಸಿಗ್ನಲ್ ಇಲ್ಲದೆಯೂ ಕೆಲಸ ಮಾಡುವ ಮಾರ್ಗಗಳು ಹಾಗೂ ಹುಡುಕಾಟ.",
        "Live traffic and faster routes as you drive" to "ನೀವು ಚಾಲನೆ ಮಾಡುತ್ತಿದ್ದಂತೆ ನೇರ ಟ್ರಾಫಿಕ್ ಮತ್ತು ವೇಗದ ಮಾರ್ಗಗಳು",
        "Lane guidance, junction signs and speed warnings" to "ಲೇನ್ ಮಾರ್ಗದರ್ಶನ, ಜಂಕ್ಷನ್ ಫಲಕಗಳು ಮತ್ತು ವೇಗ ಎಚ್ಚರಿಕೆಗಳು",
        "Offline routes and search for when signal drops" to "ಸಿಗ್ನಲ್ ಹೋದಾಗ ಆಫ್‌ಲೈನ್ ಮಾರ್ಗಗಳು ಮತ್ತು ಹುಡುಕಾಟ",
        "Everything here can be changed later in Settings." to "ಇಲ್ಲಿನ ಎಲ್ಲವನ್ನೂ ನಂತರ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಬದಲಾಯಿಸಬಹುದು.",
        "Horizon Nav uses Mapbox for the map, live traffic, search and routes. It needs your own free Mapbox access token, so the map runs on your Mapbox account (it's free for personal use)." to "Horizon Nav ನಕ್ಷೆ, ನೇರ ಟ್ರಾಫಿಕ್, ಹುಡುಕಾಟ ಮತ್ತು ಮಾರ್ಗಗಳಿಗೆ Mapbox ಬಳಸುತ್ತದೆ. ಇದಕ್ಕೆ ನಿಮ್ಮ ಸ್ವಂತ ಉಚಿತ Mapbox ಪ್ರವೇಶ ಟೋಕನ್ ಬೇಕು, ಆದ್ದರಿಂದ ನಕ್ಷೆ ನಿಮ್ಮ Mapbox ಖಾತೆಯಲ್ಲಿ ಚಲಿಸುತ್ತದೆ (ವೈಯಕ್ತಿಕ ಬಳಕೆಗೆ ಉಚಿತ).",
        "1. Go to account.mapbox.com and sign up or log in\n2. Open Tokens and copy your Default public token (it starts pk.)\n3. Paste it here" to "1. account.mapbox.com ಗೆ ಹೋಗಿ ಸೈನ್ ಅಪ್ ಅಥವಾ ಲಾಗ್ ಇನ್ ಮಾಡಿ\n2. Tokens ತೆರೆದು ನಿಮ್ಮ Default public token ನಕಲಿಸಿ (ಅದು pk. ಯಿಂದ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ)\n3. ಇಲ್ಲಿ ಅಂಟಿಸಿ",
        "Without a token the map stays blank; routes can still come from the offline pack." to "ಟೋಕನ್ ಇಲ್ಲದೆ ನಕ್ಷೆ ಖಾಲಿಯಾಗಿರುತ್ತದೆ; ಮಾರ್ಗಗಳು ಆಫ್‌ಲೈನ್ ಪ್ಯಾಕ್‌ನಿಂದ ಬರಬಹುದು.",
        "Token added: the map shows as soon as you finish setup" to "ಟೋಕನ್ ಸೇರಿಸಲಾಗಿದೆ: ನೀವು ಸೆಟಪ್ ಮುಗಿಸಿದ ತಕ್ಷಣ ನಕ್ಷೆ ಕಾಣಿಸುತ್ತದೆ",
    )

    private fun p5(): List<Pair<String, String>> = listOf(
        "TomTom key" to "TomTom ಕೀ",
        "Address search uses TomTom, as Horizon Nav always has: it finds house numbers, postcodes and businesses most accurately. TomTom is also the backup for routes and traffic. The key is free." to "ವಿಳಾಸ ಹುಡುಕಾಟ TomTom ಬಳಸುತ್ತದೆ, Horizon Nav ಯಾವಾಗಲೂ ಬಳಸಿದಂತೆ: ಇದು ಮನೆ ಸಂಖ್ಯೆಗಳು, ಪಿನ್‌ಕೋಡ್‌ಗಳು ಮತ್ತು ವ್ಯವಹಾರಗಳನ್ನು ಅತ್ಯಂತ ನಿಖರವಾಗಿ ಕಂಡುಹಿಡಿಯುತ್ತದೆ. TomTom ಮಾರ್ಗಗಳು ಮತ್ತು ಟ್ರಾಫಿಕ್‌ಗೆ ಬ್ಯಾಕಪ್ ಕೂಡ. ಕೀ ಉಚಿತ.",
        "1. Go to developer.tomtom.com and sign up or log in\n2. Open your Dashboard (Keys) and copy your API key\n3. Paste it here" to "1. developer.tomtom.com ಗೆ ಹೋಗಿ ಸೈನ್ ಅಪ್ ಅಥವಾ ಲಾಗ್ ಇನ್ ಮಾಡಿ\n2. ನಿಮ್ಮ Dashboard (Keys) ತೆರೆದು API ಕೀ ನಕಲಿಸಿ\n3. ಇಲ್ಲಿ ಅಂಟಿಸಿ",
        "Without it, search uses Mapbox and OpenStreetMap instead, which miss more house numbers. You can add it later in Settings › Keys & accounts." to "ಇದಿಲ್ಲದೆ, ಹುಡುಕಾಟ ಬದಲಿಗೆ Mapbox ಮತ್ತು OpenStreetMap ಬಳಸುತ್ತದೆ, ಅವು ಹೆಚ್ಚು ಮನೆ ಸಂಖ್ಯೆಗಳನ್ನು ತಪ್ಪಿಸುತ್ತವೆ. ನಂತರ ಸೆಟ್ಟಿಂಗ್‌ಗಳು › ಕೀಗಳು ಮತ್ತು ಖಾತೆಗಳು ನಲ್ಲಿ ಸೇರಿಸಬಹುದು.",
        "TomTom key added: search uses TomTom" to "TomTom ಕೀ ಸೇರಿಸಲಾಗಿದೆ: ಹುಡುಕಾಟ TomTom ಬಳಸುತ್ತದೆ",
        "Search in" to "ಇಲ್ಲಿ ಹುಡುಕಿ",
        "Not set · tap to search" to "ಹೊಂದಿಸಿಲ್ಲ · ಹುಡುಕಲು ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Download the pack once on Wi-Fi and routes, search, speed limits and cameras keep working with no signal. It's a large download (a few GB), so it's best done at home." to "Wi-Fi ನಲ್ಲಿ ಒಮ್ಮೆ ಪ್ಯಾಕ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ಸಿಗ್ನಲ್ ಇಲ್ಲದೆಯೂ ಮಾರ್ಗಗಳು, ಹುಡುಕಾಟ, ವೇಗ ಮಿತಿಗಳು ಮತ್ತು ಕ್ಯಾಮೆರಾಗಳು ಕೆಲಸ ಮಾಡುತ್ತವೆ. ಇದು ದೊಡ್ಡ ಡೌನ್‌ಲೋಡ್ (ಕೆಲವು GB), ಆದ್ದರಿಂದ ಮನೆಯಲ್ಲಿ ಮಾಡುವುದು ಉತ್ತಮ.",
        "Change area" to "ಪ್ರದೇಶ ಬದಲಾಯಿಸಿ",
        "Offline pack installed" to "ಆಫ್‌ಲೈನ್ ಪ್ಯಾಕ್ ಸ್ಥಾಪಿಸಲಾಗಿದೆ",
