        "You can do this later in Settings › Offline maps." to "ಇದನ್ನು ನಂತರ ಸೆಟ್ಟಿಂಗ್‌ಗಳು › ಆಫ್‌ಲೈನ್ ನಕ್ಷೆಗಳು ನಲ್ಲಿ ಮಾಡಬಹುದು.",
        "Allow" to "ಅನುಮತಿಸಿ",
        "Needed to show where you are and guide you" to "ನೀವು ಎಲ್ಲಿದ್ದೀರಿ ಎಂದು ತೋರಿಸಲು ಮತ್ತು ಮಾರ್ಗದರ್ಶಿಸಲು ಬೇಕು",
