        "Add your Mapbox access token in Settings > Keys & accounts first." to "ಮೊದಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು > ಕೀಗಳು ಮತ್ತು ಖಾತೆಗಳು ನಲ್ಲಿ ನಿಮ್ಮ Mapbox ಪ್ರವೇಶ ಟೋಕನ್ ಸೇರಿಸಿ.",
        "Around home" to "ಮನೆಯ ಸುತ್ತ",
