        "Offline speed limits and cameras are now ready for {0}: tap its Update (only the new files download, usually under 100 MB)." to "{0} ಗೆ ಆಫ್‌ಲೈನ್ ವೇಗ ಮಿತಿಗಳು ಮತ್ತು ಕ್ಯಾಮೆರಾಗಳು ಈಗ ಸಿದ್ಧ: ಅದರ ನವೀಕರಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ (ಹೊಸ ಫೈಲ್‌ಗಳು ಮಾತ್ರ ಡೌನ್‌ಲೋಡ್ ಆಗುತ್ತವೆ, ಸಾಮಾನ್ಯವಾಗಿ 100 MB ಗಿಂತ ಕಡಿಮೆ).",
