        "Offline mode" to "ಆಫ್‌ಲೈನ್ ಮೋಡ್",
        "Nothing goes online: no traffic, weather or online search, and the app stops looking for a signal. Routes, search, limits and cameras come from your downloaded pack. Downloads you start still work" to "ಯಾವುದೂ ಆನ್‌ಲೈನ್ ಹೋಗುವುದಿಲ್ಲ: ಟ್ರಾಫಿಕ್, ಹವಾಮಾನ ಅಥವಾ ಆನ್‌ಲೈನ್ ಹುಡುಕಾಟ ಇಲ್ಲ, ಮತ್ತು ಆ್ಯಪ್ ಸಿಗ್ನಲ್ ಹುಡುಕುವುದನ್ನು ನಿಲ್ಲಿಸುತ್ತದೆ. ಮಾರ್ಗಗಳು, ಹುಡುಕಾಟ, ಮಿತಿಗಳು ಮತ್ತು ಕ್ಯಾಮೆರಾಗಳು ನಿಮ್ಮ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ಪ್ಯಾಕ್‌ನಿಂದ ಬರುತ್ತವೆ. ನೀವು ಪ್ರಾರಂಭಿಸುವ ಡೌನ್‌ಲೋಡ್‌ಗಳು ಕೆಲಸ ಮಾಡುತ್ತವೆ",
