        "Pick up to 5. They show in this order. Tap one to add or take it off" to "5 ರವರೆಗೆ ಆರಿಸಿ. ಅವು ಈ ಕ್ರಮದಲ್ಲಿ ಕಾಣುತ್ತವೆ. ಸೇರಿಸಲು ಅಥವಾ ತೆಗೆಯಲು ಒಂದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ",
