        "Your head unit hasn't switched with the lights yet, so sunrise and sunset are used until it does. Turn on its headlight or illumination night-mode option, then switch your lights on to check" to "ನಿಮ್ಮ ಹೆಡ್ ಯೂನಿಟ್ ಇನ್ನೂ ದೀಪಗಳೊಂದಿಗೆ ಬದಲಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ಅದು ಬದಲಾಗುವವರೆಗೆ ಸೂರ್ಯೋದಯ ಮತ್ತು ಸೂರ್ಯಾಸ್ತ ಬಳಸಲಾಗುತ್ತದೆ. ಅದರ ಹೆಡ್‌ಲೈಟ್ ಅಥವಾ ಇಲ್ಯುಮಿನೇಶನ್ ರಾತ್ರಿ-ಮೋಡ್ ಆಯ್ಕೆ ಆನ್ ಮಾಡಿ, ನಂತರ ಪರಿಶೀಲಿಸಲು ದೀಪಗಳನ್ನು ಆನ್ ಮಾಡಿ",
