        "Your tracks" to "ನಿಮ್ಮ ಟ್ರ್ಯಾಕ್‌ಗಳು",
        "No saved places yet." to "ಇನ್ನೂ ಉಳಿಸಿದ ಸ್ಥಳಗಳಿಲ್ಲ.",
