        "Road name, arrow, tunnels, media, locking" to "ರಸ್ತೆ ಹೆಸರು, ಬಾಣ, ಸುರಂಗಗಳು, ಮಾಧ್ಯಮ, ಲಾಕ್",
        "Light, weather & 3D" to "ಬೆಳಕು, ಹವಾಮಾನ ಮತ್ತು 3D",
