        "Traffic, lights, cameras, signs, lamps" to "ಸಂಚಾರ, ದೀಪಗಳು, ಕ್ಯಾಮೆರಾಗಳು, ಫಲಕಗಳು, ಬೀದಿದೀಪಗಳು",
        "Brightness, sizes, speed, card positions, units" to "ಹೊಳಪು, ಗಾತ್ರಗಳು, ವೇಗ, ಕಾರ್ಡ್ ಸ್ಥಾನಗಳು, ಘಟಕಗಳು",
